(()=>{window.__qaThreads=null;(async()=>{try{
const all=await new Promise((resolve,reject)=>{
  const req=indexedDB.open('xray-chat-history-v1',1);
  req.onupgradeneeded=()=>req.result.createObjectStore('projects',{keyPath:'projectId'});
  req.onsuccess=()=>{const db=req.result;const q=db.transaction('projects').objectStore('projects').getAll();
    q.onsuccess=()=>{db.close();resolve(q.result||[])};q.onerror=()=>{db.close();reject(q.error)}};
  req.onerror=()=>reject(req.error)});
const needles=['The user is asking','The user wants me to','The user has asked','The prior checkpoint','I should now','Let me think'];
const out=[];let threadIndex=0;
for(const p of all) for(const t of (p.threads||[])){
  const entries=t.entries||[];
  const hits=entries.filter(e=>e.kind==='assistant'&&needles.some(n=>(e.text||'').includes(n)))
    .map(e=>({needles:needles.filter(n=>(e.text||'').includes(n)),chars:(e.text||'').length,text:(e.text||'').slice(0,260)}));
  out.push({threadIndex:threadIndex++,projectId:p.projectId,threadId:t.id,
    threadKeys:Object.keys(t),
    createdAt:t.createdAt??null,updatedAt:t.updatedAt??null,title:t.title??null,
    total:entries.length,
    user:entries.filter(e=>e.kind==='user').length,
    assistant:entries.filter(e=>e.kind==='assistant').length,
    tool:entries.filter(e=>e.kind==='tool').length,
    firstUser:((entries.find(e=>e.kind==='user')||{}).text||'').slice(0,140),
    lastAssistant:((entries.filter(e=>e.kind==='assistant').at(-1)||{}).text||'').slice(0,200),
    planningHits:hits});
}
window.__qaThreads={projectCount:all.length,threadCount:out.length,threads:out};
}catch(e){window.__qaThreads={error:String(e)}}})();return 'dumping threads'})()
